function initChefMenus(){
  const dropdowns=[...document.querySelectorAll('.nav-dropdown')];
  if(!dropdowns.length) return;
  const closeAll=(except)=>{
    dropdowns.forEach(d=>{
      if(d===except) return;
      d.classList.remove('is-open');
      const t=d.querySelector('.nav-trigger');
      if(t) t.setAttribute('aria-expanded','false');
    });
  };
  dropdowns.forEach(drop=>{
    const trigger=drop.querySelector('.nav-trigger');
    const menu=drop.querySelector('.nav-menu');
    if(!trigger||!menu) return;
    const open=()=>{
      closeAll(drop);
      drop.classList.add('is-open');
      trigger.setAttribute('aria-expanded','true');
    };
    const close=()=>{
      drop.classList.remove('is-open');
      trigger.setAttribute('aria-expanded','false');
    };
    trigger.addEventListener('click',ev=>{
      ev.preventDefault();
      drop.classList.contains('is-open') ? close() : open();
    });
    trigger.addEventListener('keydown',ev=>{
      if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();drop.classList.contains('is-open')?close():open();}
      if(ev.key==='ArrowDown'){ev.preventDefault();open();menu.querySelector('a')?.focus();}
      if(ev.key==='Escape'){close();trigger.focus();}
    });
    menu.addEventListener('keydown',ev=>{
      if(ev.key==='Escape'){close();trigger.focus();}
    });
    menu.addEventListener('click',ev=>{
      if(ev.target.closest('a')) close();
    });
  });
  document.addEventListener('click',ev=>{
    if(!ev.target.closest('.nav-dropdown')) closeAll();
  });
  window.addEventListener('scroll',()=>closeAll(),{passive:true});
  window.addEventListener('resize',()=>closeAll(),{passive:true});
}

document.addEventListener('DOMContentLoaded',initChefMenus);

