function shuffledItalianQuoteDeck(last){
  const deck=ITALIAN_QUOTES.map((_,index)=>index);
  for(let i=deck.length-1;i>0;i-=1){
    const j=Math.floor(Math.random()*(i+1));
    [deck[i],deck[j]]=[deck[j],deck[i]];
  }
  if(deck.length>1&&deck[deck.length-1]===last){
    [deck[0],deck[deck.length-1]]=[deck[deck.length-1],deck[0]];
  }
  return deck;
}

function nextItalianQuote(){
  let state={deck:[],last:-1};
  try{
    const saved=JSON.parse(localStorage.getItem('chefMalgeriItalianQuoteDeckV2')||'null');
    if(saved&&Array.isArray(saved.deck)&&Number.isInteger(saved.last))state=saved;
  }catch(_error){}
  state.deck=state.deck.filter(index=>Number.isInteger(index)&&index>=0&&index<ITALIAN_QUOTES.length);
  if(!state.deck.length)state.deck=shuffledItalianQuoteDeck(state.last);
  const index=state.deck.pop();
  state.last=index;
  try{localStorage.setItem('chefMalgeriItalianQuoteDeckV2',JSON.stringify(state));}catch(_error){}
  return ITALIAN_QUOTES[index];
}

function initItalianQuotes(){
  document.querySelectorAll('[data-italian-quote]').forEach(slot=>{
    const quote=nextItalianQuote();
    const text=slot.querySelector('p');
    const source=slot.querySelector('cite');
    if(text)text.textContent='“'+quote.text+'”';
    if(source){source.textContent='';source.hidden=true;}
    slot.removeAttribute('hidden');
  });
}

document.addEventListener('DOMContentLoaded',initItalianQuotes);